export function resolveCatalogImage(image,crop){const v=String(image||''),m=/^catalog:(shopcart|brewbliss|swimshop)$/.exec(v);if(!m)return {image:v,crop};const map=legacyCrops[m[1]],key=crop&&typeof crop==='object'?[crop.x,crop.y,crop.w,crop.h].map(Math.round).join(','):'';return {image:'catalog:'+m[1]+'/'+(map[key]||map['']),crop:null};}
